  },
  "tags": [
    "typescript",
    "effect",
    "plan",
    "sqlite"
  ],
  "keywords": [
    "typescript",
    "effect",
    "plan",
    "sqlite"
  ],
  "engines": {
    "node": ">=22.19.0"
